'use client';

import { Eye, GripVertical, Plus, Trash2 } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import { CodeSnippet } from '@/registry/default/ui/code/code-snippet';
import { Input } from '@/registry/default/ui/input';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/default/ui/popover';
import {
  Sortable,
  SortableContent,
  SortableItem,
  SortableItemHandle,
  SortableOverlay,
} from '@/registry/default/ui/sortable';

type TKeyValuePair = {
  id: string;
  key: string;
  value: string;
};

let counter = 0;
function uniqueId() {
  return `kv-${Date.now()}-${++counter}`;
}

type TKeyValueInputSize = 'sm' | 'md' | 'lg';

// A row only reads as one control if every part of it grows together, so the
// per-size decisions live here rather than at each call site.
//
// The row and the footer are on separate steps on purpose. `rowIcon` sits beside
// the inputs and must match their height exactly. `footerIcon` sits beside the
// add button and must match *that* instead, so the two footer controls never
// disagree. `gutter` reserves the remove-button column (its width plus the row
// gap) so the footer lines up under the inputs.
//
// At `lg` the add button stays on the md step: the button scale jumps to px-8 at
// lg, which reads as oversized under the fields. `addIcon` is explicit because
// only the icon-* sizes set an svg size — a text button leaves its icon at
// Lucide's 24px default.
const sizeConfig: Record<
  TKeyValueInputSize,
  {
    input: TKeyValueInputSize;
    button: TKeyValueInputSize;
    rowIcon: 'icon-sm' | 'icon-md' | 'icon-lg';
    footerIcon: 'icon-sm' | 'icon-md' | 'icon-lg';
    addIcon: string;
    gutter: string;
  }
> = {
  sm: {
    input: 'sm',
    button: 'sm',
    rowIcon: 'icon-sm',
    footerIcon: 'icon-sm',
    addIcon: 'size-3.5',
    gutter: 'pr-9',
  },
  md: {
    input: 'md',
    button: 'md',
    rowIcon: 'icon-md',
    footerIcon: 'icon-md',
    addIcon: 'size-4',
    gutter: 'pr-10',
  },
  lg: {
    input: 'lg',
    button: 'md',
    rowIcon: 'icon-lg',
    footerIcon: 'icon-md',
    addIcon: 'size-4',
    gutter: 'pr-11',
  },
};

type TKeyValueInputProps = {
  value?: TKeyValuePair[];
  onValueChange?: (pairs: TKeyValuePair[]) => void;
  defaultValue?: TKeyValuePair[];
  keyPlaceholder?: string;
  valuePlaceholder?: string;
  addLabel?: string;
  showJson?: boolean;
  sortable?: boolean;
  disabled?: boolean;
  size?: TKeyValueInputSize;
  className?: string;
};

function KeyValueInput({
  value: valueProp,
  onValueChange,
  defaultValue,
  keyPlaceholder = 'Key',
  valuePlaceholder = 'Value',
  addLabel = 'Add row',
  showJson = false,
  sortable = true,
  disabled = false,
  size = 'md',
  className,
}: TKeyValueInputProps) {
  const [internalValue, setInternalValue] = React.useState<TKeyValuePair[]>(
    () => defaultValue ?? [{ id: uniqueId(), key: '', value: '' }]
  );

  const isControlled = valueProp !== undefined;
  const pairs = isControlled ? valueProp : internalValue;

  const setPairs = React.useCallback(
    (next: TKeyValuePair[] | ((prev: TKeyValuePair[]) => TKeyValuePair[])) => {
      const resolved = typeof next === 'function' ? next(pairs) : next;
      if (!isControlled) {
        setInternalValue(resolved);
      }
      onValueChange?.(resolved);
    },
    [pairs, isControlled, onValueChange]
  );

  const handleAdd = React.useCallback(() => {
    setPairs((prev) => [...prev, { id: uniqueId(), key: '', value: '' }]);
  }, [setPairs]);

  const handleRemove = React.useCallback(
    (id: string) => {
      setPairs((prev) => prev.filter((pair) => pair.id !== id));
    },
    [setPairs]
  );

  const handleUpdate = React.useCallback(
    (id: string, field: 'key' | 'value', fieldValue: string) => {
      setPairs((prev) =>
        prev.map((pair) =>
          pair.id === id ? { ...pair, [field]: fieldValue } : pair
        )
      );
    },
    [setPairs]
  );

  const rows = pairs.map((pair) => (
    <KeyValueRow
      key={pair.id}
      pair={pair}
      keyPlaceholder={keyPlaceholder}
      valuePlaceholder={valuePlaceholder}
      disabled={disabled}
      canRemove={pairs.length > 1}
      sortable={sortable}
      size={size}
      onUpdate={handleUpdate}
      onRemove={handleRemove}
    />
  ));

  return (
    <div className={cn('flex flex-col gap-2', className)}>
      {sortable ? (
        <Sortable
          value={pairs}
          onValueChange={setPairs}
          getItemValue={(pair) => pair.id}
          orientation="vertical"
          flatCursor
        >
          <SortableContent className="flex flex-col gap-2">
            {rows}
          </SortableContent>
          <SortableOverlay>
            {({ value: activeId }) => {
              const activePair = pairs.find((p) => p.id === activeId);
              if (!activePair) return null;

              return (
                <KeyValueRow
                  pair={activePair}
                  keyPlaceholder={keyPlaceholder}
                  valuePlaceholder={valuePlaceholder}
                  disabled
                  canRemove={false}
                  sortable
                  size={size}
                  onUpdate={() => {}}
                  onRemove={() => {}}
                />
              );
            }}
          </SortableOverlay>
        </Sortable>
      ) : (
        <div className="flex flex-col gap-2">{rows}</div>
      )}
      <div
        className={cn(
          'flex items-center justify-start gap-2',
          sortable && sizeConfig[size].gutter
        )}
      >
        <Button
          type="button"
          variant="outline"
          size={sizeConfig[size].button}
          onClick={handleAdd}
          disabled={disabled}
          className="gap-1.5"
        >
          <Plus className={sizeConfig[size].addIcon} />
          {addLabel}
        </Button>
        {showJson && <KeyValueJsonPreview pairs={pairs} size={size} />}
      </div>
    </div>
  );
}

type TKeyValueRowProps = {
  pair: TKeyValuePair;
  keyPlaceholder: string;
  valuePlaceholder: string;
  disabled: boolean;
  canRemove: boolean;
  sortable: boolean;
  size: TKeyValueInputSize;
  onUpdate: (id: string, field: 'key' | 'value', value: string) => void;
  onRemove: (id: string) => void;
};

function KeyValueRowContent({
  pair,
  keyPlaceholder,
  valuePlaceholder,
  disabled,
  canRemove,
  sortable,
  size,
  onUpdate,
  onRemove,
}: TKeyValueRowProps) {
  return (
    <>
      {sortable && (
        <SortableItemHandle asChild>
          <Button
            type="button"
            variant="outline"
            size={sizeConfig[size].rowIcon}
            className="shrink-0"
            disabled={disabled}
          >
            <GripVertical className="text-muted-foreground" />
            <span className="sr-only">Drag to reorder</span>
          </Button>
        </SortableItemHandle>
      )}
      <Input
        size={sizeConfig[size].input}
        placeholder={keyPlaceholder}
        value={pair.key}
        onChange={(e) => onUpdate(pair.id, 'key', e.target.value)}
        disabled={disabled}
        className="flex-1"
      />
      <Input
        size={sizeConfig[size].input}
        placeholder={valuePlaceholder}
        value={pair.value}
        onChange={(e) => onUpdate(pair.id, 'value', e.target.value)}
        disabled={disabled}
        className="flex-1"
      />
      <Button
        type="button"
        variant="outline"
        size={sizeConfig[size].rowIcon}
        onClick={() => onRemove(pair.id)}
        disabled={disabled || !canRemove}
      >
        <Trash2 />
        <span className="sr-only">Remove row</span>
      </Button>
    </>
  );
}

function KeyValueRow(props: TKeyValueRowProps) {
  if (props.sortable) {
    return (
      <SortableItem
        value={props.pair.id}
        className="flex items-center gap-2 rounded-md"
        disabled={props.disabled}
      >
        <KeyValueRowContent {...props} />
      </SortableItem>
    );
  }

  return (
    <div className="flex items-center gap-2 rounded-md">
      <KeyValueRowContent {...props} />
    </div>
  );
}

function KeyValueJsonPreview({
  pairs,
  size,
}: {
  pairs: TKeyValuePair[];
  size: TKeyValueInputSize;
}) {
  const json = React.useMemo(() => {
    const obj: Record<string, string> = {};
    for (const pair of pairs) {
      if (pair.key) obj[pair.key] = pair.value;
    }

    return JSON.stringify(obj, null, 2);
  }, [pairs]);

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          size={sizeConfig[size].footerIcon}
          className="justify-center"
        >
          <Eye />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-80 p-0 border-none">
        <CodeSnippet code={json} language="json" canCopy={false} size="sm" />
      </PopoverContent>
    </Popover>
  );
}

function recordToPairs(
  record: Record<string, unknown> | undefined | null
): TKeyValuePair[] {
  const entries = Object.entries(record ?? {});
  if (entries.length === 0) return [{ id: uniqueId(), key: '', value: '' }];

  return entries.map(([key, value]) => ({
    id: `kv-record-${key}`,
    key,
    value: String(value ?? ''),
  }));
}

function pairsToRecord(pairs: TKeyValuePair[]): Record<string, string> {
  const obj: Record<string, string> = {};
  for (const pair of pairs) {
    if (pair.key) obj[pair.key] = pair.value;
  }

  return obj;
}

export {
  KeyValueInput,
  pairsToRecord,
  recordToPairs,
  type TKeyValueInputProps,
  type TKeyValueInputSize,
  type TKeyValuePair,
};
